import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CC9cRD7J.js";const i="/Staff-wiki/banner-staffplus.svg",n="/Staff-wiki/guide-moderation-flow.svg",f=JSON.parse('{"title":"Introducción a StaffPlus","description":"","frontmatter":{},"headers":[],"relativePath":"guia/introduccion.md","filePath":"guia/introduccion.md","lastUpdated":1793576062000}'),s={name:"guia/introduccion.md"};function d(l,e,c,u,p,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="introduccion-a-staffplus" tabindex="-1">Introducción a StaffPlus <a class="header-anchor" href="#introduccion-a-staffplus" aria-label="Permalink to &quot;Introducción a StaffPlus&quot;">​</a></h1><p><img src="'+i+'" alt="Banner StaffPlus v5.0.4"></p><p><strong>StaffPlus</strong> es un plugin integral de administración y moderación diseñado específicamente para servidores de Minecraft. Su propósito es brindar al equipo de moderación (helpers, moderadores y administradores) todas las herramientas necesarias para supervisar el servidor, detectar tramposos y sancionar infracciones sin interferir con la experiencia normal de juego.</p><hr><h2 id="⚡-flujo-de-moderacion-en-el-servidor" tabindex="-1">⚡ Flujo de Moderación en el Servidor <a class="header-anchor" href="#⚡-flujo-de-moderacion-en-el-servidor" aria-label="Permalink to &quot;⚡ Flujo de Moderación en el Servidor&quot;">​</a></h2><p><img src="'+n+'" alt="Flujo Operativo del Equipo de Moderación"></p><hr><h2 id="🌟-caracteristicas-principales" tabindex="-1">🌟 Características Principales <a class="header-anchor" href="#🌟-caracteristicas-principales" aria-label="Permalink to &quot;🌟 Características Principales&quot;">​</a></h2><ul><li><strong>Modo Staff Modular (<code>/staff</code>):</strong> Al activarse, guarda el inventario real del moderador y le entrega una barra de herramientas táctica (compás de propulsión, teleport aleatorio, vanish, CPS test, inspección, etc.).</li><li><strong>Blindaje Anti-Exploits:</strong> Los objetos de moderación están totalmente bloqueados; no pueden tirarse, intercambiarse a la mano secundaria, ni traspasarse a cofres o soportes de armaduras.</li><li><strong>Sistema Integral de Bans e IP Bans:</strong> Permite aplicar sanciones temporales o definitivas por nombre o IP, además de un panel gráfico intuitivo (<code>/bangui</code>).</li><li><strong>Inspección Profunda (<code>/examine</code>):</strong> Muestra el contenido del inventario, armadura, ping, nivel de comida, coordenadas, historial de infracciones y botones de sanción instantánea.</li><li><strong>Alertas de X-Ray y Menciones:</strong> Notifica al equipo cuando un usuario extrae diamantes, esmeraldas u otros minerales de forma sospechosa.</li><li><strong>Control de Chat:</strong> Limpieza rápida de chat (<code>/chat clear</code>), modo lento (<code>/chat slow</code>) y filtro automático de dominios y palabras malsonantes.</li></ul><hr><h2 id="📋-requisitos-del-servidor" tabindex="-1">📋 Requisitos del Servidor <a class="header-anchor" href="#📋-requisitos-del-servidor" aria-label="Permalink to &quot;📋 Requisitos del Servidor&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Componente</th><th style="text-align:left;">Requisito Mínimo</th><th style="text-align:left;">Recomendado</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Software de Servidor</strong></td><td style="text-align:left;">Paper, Purpur o Spigot 1.8+</td><td style="text-align:left;"><strong>Paper 26.3</strong> / Paper 1.21+</td></tr><tr><td style="text-align:left;"><strong>Java</strong></td><td style="text-align:left;">Java 8 (para versiones antiguas)</td><td style="text-align:left;"><strong>Java 21 / Java 25 LTS</strong></td></tr><tr><td style="text-align:left;"><strong>Permisos</strong></td><td style="text-align:left;">LuckPerms, PermissionsEx o similar</td><td style="text-align:left;"><strong>LuckPerms</strong></td></tr><tr><td style="text-align:left;"><strong>Base de Datos</strong></td><td style="text-align:left;">Archivos planos (.yml)</td><td style="text-align:left;"><strong>MySQL / MariaDB</strong> (para networks)</td></tr></tbody></table><hr><h2 id="🚀-novedades-de-la-version-5-0-4" tabindex="-1">🚀 Novedades de la Versión 5.0.4 <a class="header-anchor" href="#🚀-novedades-de-la-version-5-0-4" aria-label="Permalink to &quot;🚀 Novedades de la Versión 5.0.4&quot;">​</a></h2><ul><li><strong>Soporte Paper 26.x:</strong> Incorporación del nuevo adaptador de protocolo <code>v26_3_R1</code> con detección inteligente del versionado moderno de Paper.</li><li><strong>Módulo de Bans Renovado:</strong> Persistencia independiente en <code>bans.yml</code>, historial cruzado de IPs y nombres para detección de multicuentas.</li><li><strong>Solución de Bugs Críticos:</strong><ul><li>Corregido el lanzamiento involuntario del Ojo de Ender en el gadget de RTP.</li><li>Solucionado el error de arranque por <code>bans.yml</code> no encontrado en el JAR.</li><li>Implementado <code>EntityPickupItemEvent</code> para impedir que moderadores en vanish recojan objetos del suelo.</li></ul></li></ul>',15)])])}const h=a(s,[["render",d]]);export{f as __pageData,h as default};
